class Solution {
    int ans;
    void dfs(TreeNode* node, int leftLen, int rightLen) {
        if (!node) return;
        if (leftLen > ans) ans = leftLen;
        if (rightLen > ans) ans = rightLen;
        dfs(node->left, rightLen + 1, 0);
        dfs(node->right, 0, leftLen + 1);
    }
public:
    int longestZigZag(TreeNode* root) {
        ans = 0;
        dfs(root, 0, 0);
        return ans;
    }
};
